"""AI chart analyst: structured, educational explanation of a chart context."""
import json
import logging
import time
from dataclasses import dataclass
from typing import Literal

import anthropic
from pydantic import BaseModel, ValidationError

log = logging.getLogger(__name__)

DISCLAIMER = (
    "Educational analysis generated by AI from the chart data shown. It is not investment "
    "advice or a recommendation to buy, sell or hold any security. Verify independently "
    "and consult a SEBI-registered adviser before making investment decisions."
)

SYSTEM_PROMPT = """You are a technical-analysis explainer inside a charting platform. A user is \
looking at a price chart and asked "what is this chart showing?". You receive a JSON context with \
the chart's recent bars and pre-computed indicator values.

How to answer:
- Explain what the chart shows: trend and its strength, momentum, volatility, volume, and the \
nearby support/resistance levels, in plain language a retail trader can follow. Mention the \
timeframe, because the same stock can look different on another one.
- Every number you cite (prices, levels, indicator readings, percentages) must come from the \
context. Do not compute new levels, targets or probabilities. If something is not in the \
context, say it is not available rather than estimating it.
- Use key_levels only from levels_from_swings, moving averages, Bollinger bands, VWAP or \
supertrend values in the context, and say which one each level comes from.
- When indicators disagree, say so plainly; do not force a single story.
- This is education, not advice. Never tell the user to buy, sell, hold, enter or exit, and \
give no price targets or stop-loss suggestions. Describe conditions ("a close above X would \
mean ...") instead of instructions. The platform shows a regulatory disclaimer separately, so \
do not add one.
- Keep summary to 2-4 sentences and each list item to one sentence."""

LevelSource = Literal["swing", "ema", "bollinger", "vwap", "supertrend", "window_high_low"]


class KeyLevel(BaseModel):
    kind: Literal["support", "resistance"]
    price: float
    source: LevelSource
    note: str


class ChartAnalysis(BaseModel):
    summary: str
    trend: Literal["uptrend", "downtrend", "sideways"]
    trend_strength: Literal["weak", "moderate", "strong"]
    momentum: str
    volatility: str
    volume: str
    key_levels: list[KeyLevel]
    signals_conflicting: list[str]
    what_to_watch: list[str]


def _schema() -> dict:
    """Hand-written JSON schema matching ChartAnalysis (structured-output friendly)."""
    s = {"type": "string"}
    arr = {"type": "array", "items": s}
    level = {
        "type": "object",
        "properties": {
            "kind": {"type": "string", "enum": ["support", "resistance"]},
            "price": {"type": "number"},
            "source": {"type": "string", "enum": list(LevelSource.__args__)},
            "note": s,
        },
        "required": ["kind", "price", "source", "note"],
        "additionalProperties": False,
    }
    props = {
        "summary": s,
        "trend": {"type": "string", "enum": ["uptrend", "downtrend", "sideways"]},
        "trend_strength": {"type": "string", "enum": ["weak", "moderate", "strong"]},
        "momentum": s, "volatility": s, "volume": s,
        "key_levels": {"type": "array", "items": level},
        "signals_conflicting": arr,
        "what_to_watch": arr,
    }
    return {"type": "object", "properties": props, "required": list(props), "additionalProperties": False}


class AnalystUnavailable(RuntimeError):
    """No credentials / API unreachable: surfaced as 503."""


class AnalystError(RuntimeError):
    """The model returned something unusable (refusal, truncation, bad JSON)."""


@dataclass
class AnalysisResult:
    analysis: ChartAnalysis
    model: str
    request_id: str | None
    input_tokens: int
    output_tokens: int
    latency_ms: int


class ChartAnalyst:
    def __init__(self, client: anthropic.AsyncAnthropic | None = None, *, api_key: str = "",
                 model: str = "claude-opus-5-5", effort: str = "medium", fallbacks: bool = True):
        self._client = client
        self._api_key = api_key
        self.model = model
        self.effort = effort
        self.fallbacks = fallbacks

    @property
    def client(self) -> anthropic.AsyncAnthropic:
        if self._client is None:
            # explicit key from .env if given; otherwise the SDK resolves
            # ANTHROPIC_API_KEY / ANTHROPIC_AUTH_TOKEN / an `ant auth login` profile
            self._client = (anthropic.AsyncAnthropic(api_key=self._api_key) if self._api_key
                            else anthropic.AsyncAnthropic())
        return self._client

    async def explain(self, context: dict) -> AnalysisResult:
        kwargs: dict = {}
        if self.fallbacks:
            # on a policy refusal the API re-runs the request on a fallback model
            kwargs = {"betas": ["server-side-fallback-2026-07-01"], "fallbacks": "default"}
        started = time.perf_counter()
        try:
            resp = await self.client.beta.messages.create(
                model=self.model,
                max_tokens=16000,
                system=SYSTEM_PROMPT,
                output_config={"effort": self.effort,
                               "format": {"type": "json_schema", "schema": _schema()}},
                messages=[{"role": "user", "content":
                           "Chart context:\n" + json.dumps(context, separators=(",", ":"))}],
                **kwargs,
            )
        except (anthropic.AuthenticationError, anthropic.PermissionDeniedError) as e:
            raise AnalystUnavailable(f"Anthropic credentials rejected: {e.message}") from e
        except anthropic.RateLimitError as e:
            raise AnalystUnavailable("AI analyst is rate limited; try again shortly") from e
        except anthropic.APIConnectionError as e:
            raise AnalystUnavailable("could not reach the Anthropic API") from e
        except anthropic.APIStatusError as e:
            if e.status_code >= 500:
                raise AnalystUnavailable(f"Anthropic API error {e.status_code}") from e
            raise AnalystError(f"Anthropic API rejected the request: {e.message}") from e
        except TypeError as e:  # SDK raises this at request time when no credentials resolve
            if "authentication" not in str(e):
                raise
            raise AnalystUnavailable(
                "AI analyst needs Anthropic credentials: set ANTHROPIC_API_KEY in .env") from e
        latency_ms = int(1000 * (time.perf_counter() - started))

        if resp.stop_reason == "refusal":
            raise AnalystError("the model declined to analyse this chart")
        if resp.stop_reason == "max_tokens":
            raise AnalystError("analysis was truncated (max_tokens)")
        text = next((b.text for b in resp.content if b.type == "text"), None)
        if text is None:
            raise AnalystError("model returned no text")
        try:
            analysis = ChartAnalysis.model_validate_json(text)
        except ValidationError as e:
            raise AnalystError(f"model output did not match schema: {e.error_count()} errors") from e
        return AnalysisResult(analysis, resp.model, getattr(resp, "_request_id", None),
                              resp.usage.input_tokens, resp.usage.output_tokens, latency_ms)
